    if (embeddable == null) {
        writeNull();
        return;
    }
    if (embeddable instanceof String) {
        writeString((String) embeddable);
    } else if (embeddable instanceof Number) {
        if (embeddable instanceof Integer) {
            writeNumber(((Integer) embeddable).intValue());
        } else if (embeddable instanceof Long) {
            writeNumber(((Long) embeddable).longValue());
        } else if (embeddable instanceof Double) {
            writeNumber(((Double) embeddable).doubleValue());
        } else if (embeddable instanceof Float) {
            writeNumber(((Float) embeddable).floatValue());
        } else if (embeddable instanceof Short) {
            writeNumber(((Short) embeddable).shortValue());
        } else if (embeddable instanceof AtomicInteger) {
            writeNumber(((AtomicInteger) embeddable).get());
        } else if (embeddable instanceof AtomicLong) {
            writeNumber(((AtomicLong) embeddable).get());
        } else if (embeddable instanceof BigDecimal) {
            writeNumber((BigDecimal) embeddable);
        } else if (embeddable instanceof BigInteger) {
            writeNumber((BigInteger) embeddable);
        } else {
            writeNumber(((Number) embeddable).doubleValue());
        }
    } else if (embeddable instanceof Boolean) {
        writeBoolean((Boolean) embeddable);
    } else {
        throw new IllegalArgumentException("Unsupported embedded Object type: " + embeddable.getClass().getName());
    }
}

